def divide(a, b):
    try:
        result = a / b
    except ZeroDivisionError:
        print("На ноль делить нельзя")
        return None
    else:
        return result
    finally:
        print("Расчёт завершён")

print(divide(10, 2))   # Расчёт завершён / 5.0
print(divide(10, 0))   # На ноль делить нельзя / Расчёт завершён / None

