class InsufficientFundsError(Exception):
    pass


def withdraw(balance, amount):
    if amount <= 0:
        raise ValueError("сумма должна быть положительной")
    if amount > balance:
        raise InsufficientFundsError(f"нужно {amount}, есть {balance}")
    return balance - amount
